// initPostDataSourceCmd initializes the post-data-source command.
func initPostDataSourceCmd(parent *cobra.Command) error {
	var cmd = &cobra.Command{
		Use:     "post",
		Short:   "Create a data source",
		Long:    "Tests the connection and validates each assignment query against the warehouse before saving. The Managed Warehouse, Google Analytics and Event Forwarders are set up in the app.",
		Example: "  growthbook data-sources post --name <value> --connection '{\"type\":\"databricks\",\"authType\":\"oauth-m2m\",\"host\":\"muffled-squid.name\",\"port\":694435,\"path\":\"/lib\",\"catalog\":\"<value>\"}'",
		RunE:    runPostDataSourceCmd,
	}
	flagutil.RegisterFlags(cmd, postDataSourceCmdMeta)
	if err := flagutil.ValidateMeta[operations.PostDataSourceRequest](postDataSourceCmdMeta); err != nil {
		return fmt.Errorf("invalid metadata for post-data-source: %w", err)
	}
	cmd.Flags().String("body", "", "Request body as JSON (alternative to individual flags). Can also be provided via stdin.")
	parent.AddCommand(cmd)
	return nil
}

// runPostDataSourceCmd executes the post-data-source command.
func runPostDataSourceCmd(cmd *cobra.Command, args []string) error {
	if usage.UsageRequested(cmd) {
		return usage.EmitSchema(cmd, cmd.OutOrStdout())
	}
	if interactive.ShouldPrompt(cmd, postDataSourceCmdMeta) {
		if err := interactive.PromptAndSetFlags(cmd, postDataSourceCmdMeta); err != nil {
			return err
		}
	}
	request, err := flagutil.BuildRequest[operations.PostDataSourceRequest](cmd, postDataSourceCmdMeta, "", "body")
	if err != nil {
		return err
	}
	s, err := client.NewClient(cmd)
	if err != nil {
		return err
	}
	sdkOpts, err := output.PrepareCallOpts(cmd)
	if err != nil {
		return err
	}
	// Dry-run: force skip deserialization so the synthetic empty response
	// does not cause parse failures in typed response handling.
	if client.IsDryRun(cmd) {
		sdkOpts = append(sdkOpts, operations.WithSkipDeserialization())
	}
	if err := output.ValidateGlobalServerIndex(cmd, len(sdk.ServerList)); err != nil {
		return err
	}
	if output.WantsRawJSON(cmd) {
		sdkOpts = append(sdkOpts, operations.WithSkipDeserialization())
	}
	res, err := s.DataSources.PostDataSource(cmd.Context(), *request, sdkOpts...)
	if err != nil {
		return output.Error(cmd, err)
	}

	if err := output.Result(cmd, res); err != nil {
		return err
	}
	return nil
}
